    internal static async Task<WatchProductionView> Drain(IServiceProvider s, Fixture f, Guid id)
    { var watch = s.GetRequiredService<IWatchFactory>(); for (var i = 0; i < 80; i++) { var p = await watch.InspectAsync(f.Context.Owner, f.Context.Universe, id, default); if (p.State is "Review" or "Approved" or "Failed" or "Cancelled") return p; if (!await watch.ProcessNextAsync(default)) await Task.Delay(100); } throw new InvalidOperationException("WATCH queue did not settle."); }
